import type { ServiceSlug } from "./content";

/**
 * Printfix's own work, as published on the five service pages of printfix.co.in.
 * Specs are Printfix's own descriptions (lightly tidied for spelling).
 * Images: public/work/<slug>-<n>.webp (+ -sm.webp at 640w), generated by scripts/prepare-images.py.
 */
export type Project = {
  slug: string;
  name: string;
  service: ServiceSlug;
  /** One-line category shown on cards, e.g. "Magnetic rigid box, Perfumery". */
  kind: string;
  specs: { label: string; value: string }[];
  images: number;
  alt: string;
  client?: string;
};

const P = (
  slug: string, name: string, service: ServiceSlug, kind: string, alt: string, images: number,
  specs: [string, string][], client?: string,
): Project => ({ slug, name, service, kind, alt, images, specs: specs.map(([label, value]) => ({ label, value })), client });

