export const img = (slug: string, n = 1, sm = false) => `/work/${slug}-${n}${sm ? "-sm" : ""}.webp`;
export const bySlug = (slug: string) => projects.find((p) => p.slug === slug)!;
export const forService = (s: ServiceSlug) => projects.filter((p) => p.service === s);
/** Projects whose own spec names offset printing. */
export const isOffset = (p: Project) => p.specs.some((s) => /offset/i.test(s.value));
export const offsetProjects = () => projects.filter(isOffset);

